const o={ui:{fig:"Fig. 1",title:"Bolso · anatomía",svgLabel:"Un dibujo isométrico del bolso forrado para el teléfono con solapa y tres compartimentos y de cómo se cose, paso a paso.",prev:"Paso anterior",dot:(a,e)=>a?`Paso ${a}: ${e}`:e,start:"Paso a paso →",next:"Siguiente →",overview:"Vista general",stepOf:(a,e)=>`Paso ${a} de ${e}`,machine:a=>`Máquina: ${a.toLowerCase()}`,inThisStep:"En este paso",takeApart:"Desarmar",putTogether:"Armar",replay:"↻ Repetir",parts:"Piezas",allSteps:"Instrucciones paso a paso",endView:"CORTE TRANSVERSAL",cutTitle:"Bolso para el teléfono · medidas de corte",cutAlt:"Esquema de corte de un bolso forrado para el teléfono con solapa: exterior, forro y entretela termoadhesiva, cada uno en una pieza larga de 57 × 19 cm y una pieza de solapa de 31 × 13 cm, más dos cuadrados de 5 × 5 cm para las presillas.",cutCaption:"Las piezas que hay que cortar, con sus medidas — las mismas del paso 1."},stitches:{straight:"Puntada recta"},labels:{cm57:"57 cm",cm19:"19 cm",cm31:"31 cm",cm13:"13 cm",cm5:"5 cm",cm11:"11 cm",outerPrint:"exterior · algodón estampado",liningSame:"forro · mismas medidas",ifaceSame:"entretela · mismas medidas",flapPieces:"piezas de la solapa",ears2:"2 × presillas",wrongSideUp:"exterior, revés arriba",ironOn:"planchar",outerOnly:"solo en el exterior",faceDown:"derecho abajo, al centro",seam05:"costura a 0,5 cm",openOut:"abrir: una T",liningSameT:"forro: la misma T",rightSides:"derecho con derecho",roundObject:"cualquier tapa redonda",roundCorners:"esquinas redondas",opening6:"abertura de 6 cm",oppositeFlap:"frente a la solapa",clipCorners:"piquetes en las esquinas",turnOut:"dar la vuelta al derecho",press:"planchar",topstitch05:"pespunte a 0,5 cm",closesOpening:"cierra la abertura",turnOver:"forro arriba",foldHalf:"doblar por la mitad",fromFold:"desde el doblez",throughBoth:"por las dos capas",twoLines:"dos costuras",openFlap:"abrir la solapa",seamsMiddle:"costuras al centro",accordion:"en acordeón",pockets3:"3 compartimentos",likeStraps:"como las asas de la tote",intoLoop:"doblar en presilla",makeTwo:"hacer dos",overTop:"doblar encima",backAndFlap:"la espalda + la solapa",earsIn:"presillas arriba",clipIt:"sujetar los lados",edgeStitch:"al ras del borde",allLayers:"por todas las capas",snapFlap:"broche: centro de la solapa",whereItLands:"donde cae",secondHalf:"segunda mitad",insidePockets:"teléfono · dinero · tarjetas"},steps:[{title:"El bolso terminado",text:"Un bolsito forrado para el teléfono, el dinero y las tarjetas: tres compartimentos por dentro, una solapa con broche de presión de plástico y dos presillas pequeñas arriba. La cadena es solo una idea — en el video no hay; a las presillas se engancha cualquier cadena o correa con mosquetones. Toca el bolso para desarmarlo."},{title:"Cortar las piezas",text:"Exterior de algodón estampado: una pieza larga de 57 × 19 cm y una pieza de solapa de 31 × 13 cm. Forro y entretela termoadhesiva: las mismas dos medidas. Dos cuadrados de 5 × 5 cm para las presillas.",details:["Del algodón estampado corta la pieza larga de 57 × 19 cm y la pieza de solapa de 31 × 13 cm.","Corta el forro igual: 57 × 19 cm y 31 × 13 cm.","Corta la entretela termoadhesiva en las mismas dos medidas — solo para las piezas exteriores.","Para las presillas corta dos cuadrados de 5 × 5 cm del algodón estampado.","Todos los márgenes de costura de este bolso son de 0,5 cm."]},{title:"Planchar la entretela",text:"Plancha la entretela en el revés de las dos piezas exteriores. El forro no lleva.",details:["Coloca la pieza larga exterior y la pieza de solapa con el revés hacia arriba.","Pon encima la entretela, con el lado del pegamento hacia abajo, borde con borde, y plánchala.","Las piezas del forro no llevan entretela."]},{title:"Coser la T",text:"Coloca la pieza de solapa derecho con derecho, atravesada en el centro de la pieza larga, con su lado de 13 cm sobre el lado largo. Cose a 0,5 cm del borde y ábrela: una T. Con el forro haz la misma T.",details:["Coloca la pieza larga con el derecho hacia arriba.","Pon encima la pieza de solapa con el derecho hacia abajo, atravesada: su lado de 13 cm justo en el centro de un lado largo, borde con borde.","Cose a lo largo de ese borde a 0,5 cm y abre la pieza de solapa: las dos piezas forman una T.","Con las piezas del forro cose otra T de la misma manera."]},{title:"Redondear la solapa",text:"Coloca la T del forro sobre la T exterior, derecho con derecho. Redondea las dos esquinas del extremo de la solapa: marca el contorno de cualquier objeto redondo y corta por la línea.",details:["Coloca la T del forro con el derecho hacia abajo sobre la T exterior, bordes parejos, y sujétalas con clips de costura.","En el extremo de la pieza de solapa marca el contorno de cualquier objeto redondo — la tapa de un frasco, un rollo de cinta adhesiva — en las dos esquinas.","Corta por las líneas: la solapa queda con las esquinas redondas."]},{title:"Coser todo el contorno",text:"Cose todo el contorno a 0,5 cm del borde, dejando una abertura de 6 cm en el centro del lado largo, frente a la solapa. Haz piquetes en las esquinas.",details:["Empieza en un extremo de la abertura: los 6 cm quedan sin coser, en el centro del lado largo, frente a la pieza de solapa.","Cose todo el contorno de la T a 0,5 cm del borde y detente en el otro extremo de la abertura.","Haz un piquete en el margen de las dos esquinas interiores de la T — antes de la línea de costura — y en las esquinas redondas, para que queden planas."]},{title:"Dar la vuelta",text:"Da la vuelta a la T al derecho por la abertura. Saca bien las esquinas y plancha.",details:["Saca toda la T por la abertura.","Saca bien las esquinas y el extremo redondo de la solapa.","Plancha en plano, con los bordes de la abertura doblados hacia dentro."]},{title:"Pespuntear todo el contorno",text:"Haz un pespunte visible por todo el contorno de la T a 0,5 cm del borde. Ese mismo pespunte cierra la abertura.",details:["Cose por todo el borde, a 0,5 cm.","En la abertura mantén parejos los bordes doblados: el pespunte la cierra."]},{title:"Doblar y marcar",text:"Gira la T con el forro hacia arriba y dobla por la mitad la pieza larga — la pieza de solapa se dobla por la mitad a lo largo. Marca líneas a 11 y 22 cm del doblez.",details:["Gira la T con el forro hacia arriba.","Dobla por la mitad la pieza larga, con el forro por dentro: el doblez pasa por el centro de la pieza de solapa, que se dobla por la mitad a lo largo.","Con la cinta métrica mide 11 cm desde el doblez y otros 11 cm desde esa marca: líneas a 11 y 22 cm del doblez. Trázalas con la regla."]},{title:"Coser las dos líneas",text:"Cose las dos líneas por las dos mitades. Ahora las mitades están unidas: estas costuras dividen el bolso en compartimentos.",details:["Cose la primera línea por las dos capas.","Cose la segunda línea de la misma manera.","Entre el doblez y la primera costura, y entre las dos costuras, las mitades forman dos lazos."]},{title:"Doblar en acordeón",text:"Vuelve a abrir en plano la pieza de solapa. Las costuras van al centro y la pieza larga se dobla en acordeón: tres compartimentos.",details:["Abre en plano la pieza de solapa.","Aplana la pieza larga de modo que su centro — el doblez — quede en el extremo de la pieza de solapa y las dos costuras vayan al centro.","Se dobla en acordeón: tres compartimentos, uno detrás de otro."]},{title:"Hacer las presillas",text:"Dobla cada cuadrado de 5 × 5 cm como las asas de la bolsa tote: por la mitad, los bordes hacia el doblez, otra vez por la mitad. Luego dóblalo por la mitad en presilla. Haz dos.",details:["Dobla el cuadrado por la mitad y ábrelo.","Lleva los dos bordes hasta ese doblez y vuelve a doblar por la mitad: una tira estrecha de cuatro capas.","Dobla la tira por la mitad en una presilla pequeña. Haz dos."]},{title:"Doblar la solapa encima",text:"Dobla la pieza larga de solapa sobre los compartimentos: pasa por debajo del fondo y sube por la espalda, y su extremo sobresale arriba como solapa. Mete una presilla en cada lado arriba, entre la espalda y los compartimentos.",details:["Dobla la pieza de solapa sobre los compartimentos. Su doblez es el fondo del bolso y cierra cada compartimento por abajo.","El resto es la espalda; su extremo sobresale arriba — esa es la solapa.","Mete una presilla en cada lado arriba, entre la espalda y los compartimentos, con el lazo hacia fuera.","Sujeta los lados con clips de costura."]},{title:"Coser los lados",text:"Cose los dos lados al ras del borde, por todas las capas y las presillas.",details:["Cose un lado al ras del borde de los dobleces, por todas las capas y la presilla.","Cose el otro lado de la misma manera."]},{title:"Poner el broche",text:"Pon una mitad del broche de presión de plástico en el centro de la solapa, sobre el pespunte. Baja la solapa, marca dónde cae y pon allí la otra mitad.",details:["Pon la primera mitad del broche en el centro del extremo redondo de la solapa, sobre la línea del pespunte.","Baja la solapa sobre el frente y marca dónde cae el broche.","Pon allí la segunda mitad.","Por dentro: el teléfono en el compartimento junto a la espalda, el dinero en el del medio, las tarjetas en el de delante."]}],legend:[{title:"Exterior",text:"algodón estampado · pieza larga de 57 × 19 cm y pieza de solapa de 31 × 13 cm"},{title:"Entretela",text:"termoadhesiva · las mismas dos medidas, solo en las piezas exteriores"},{title:"Forro",text:"algodón rosa · las mismas dos medidas, sin entretela"},{title:"Solapa",text:"la pieza de 31 × 13 cm: bajo el fondo, sube por la espalda, esquinas redondas en el extremo"},{title:"Compartimentos ×3",text:"costuras a 11 y 22 cm del doblez por las dos mitades: teléfono, dinero, tarjetas"},{title:"Presillas ×2",text:"cuadrados de 5 × 5 cm, doblados como las asas de la bolsa tote y luego en presilla"},{title:"Broche",text:"de presión, de plástico · en el centro de la solapa, sobre el pespunte"},{title:"Costuras",text:"todas a 0,5 cm · abertura de 6 cm frente a la solapa, cerrada por el pespunte a 0,5 cm en todo el contorno"}]};export{o as default};
